func TestCreateTemp(t *testing.T) {
	t.Parallel()

	nonexistentDir := filepath.Join(t.TempDir(), "_not_exists_")
	f, err := CreateTemp(nonexistentDir, "foo")
	if f != nil || err == nil {
		t.Errorf("CreateTemp(%q, `foo`) = %v, %v", nonexistentDir, f, err)
	}
}

